import sys, json, random, subprocess
sys.path.insert(0, '/app/tmp/t')
from harness import *

random.seed(1234)

ALPHA = list("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789")
SPECIAL = list("\t !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~")
BYTES_POOL = [bytes([c]) for c in range(0x20, 0x7f)] + [b"\r", b"\n", b"\t", b"\x00", b"\xff", b"\x7f"]

def rand_line(maxlen=60):
    n = random.randint(0, maxlen)
    pool = ALPHA + SPECIAL
    return "".join(random.choice(pool) for _ in range(n))

def rand_request():
    lines = [rand_line(40) for _ in range(random.randint(0, 8))]
    if random.random() < 0.5:
        lines[0:1] = ["MESSAGE " + rand_line(30) + " SIP/2.0"]
    sep = random.choice(["\r\n", "\r\n", "\r\n", "\n", "\r"])
    text = sep.join(lines)
    if random.random() < 0.7:
        text += "\r\n\r\n"
    body = bytes(random.randint(0, 255) for _ in range(random.randint(0, 20)))
    return text.encode('latin-1') + body

def rand_hexish():
    r = random.random()
    if r < 0.4:
        return rand_request().hex()
    if r < 0.5:
        return rand_request().hex().upper()
    if r < 0.6:
        s = rand_request().hex()
        return s[:-1] if len(s) % 2 else s   # odd length sometimes
    if r < 0.7:
        return "".join(random.choice("0123456789abcdefABCDEFxyz") for _ in range(random.randint(0, 40)))
    return "".join(random.choice("0123456789abcdef") for _ in range(random.randint(0, 60)))

cfg = base_config()
bad_exit = 0
reasons = {}
N = 400
for it in range(N):
    evs = []
    for _ in range(random.randint(1, 6)):
        evs.append(ev(random.randint(0, 5), random.choice(["edge", "trunk"]),
                      random.choice(["alice", "bob", None]), random.choice(["internal", "external"]),
                      rand_hexish()))
    # ensure relay events have null auth
    for e in evs:
        if e["peer"] == "trunk":
            e["auth"] = None
    evs.sort(key=lambda e: e["t"])
    rc, out, err = run(envelope(evs, cfg))
    if rc != 0:
        bad_exit += 1
        print("BAD EXIT", rc, err[:300], out[:100])
        break
    d = json.loads(out)
    for r in d["results"]:
        if r["decision"] == "reject":
            reasons[r["reason"]] = reasons.get(r["reason"], 0) + 1
        else:
            assert set(r.keys()) == {"index","decision","first","account","identity","from","pai","method","target","call_id","cseq","tag","privacy","body_sha256"}, r
print("iterations:", N, "bad exits:", bad_exit)
print("reasons seen:", reasons)

# structured fuzz: mutate a valid request
base = mkreq(headers=std_headers(body=b"abc"), body=b"abc")
mut_bad = 0
for it in range(3000):
    b = bytearray(base)
    for _ in range(random.randint(1, 3)):
        op = random.random()
        i = random.randrange(len(b))
        if op < 0.4:
            b[i] = random.randrange(256)
        elif op < 0.7:
            del b[i:i+random.randint(1,4)]
        else:
            b[i:i] = bytes([random.randrange(256) for _ in range(random.randint(1,3))])
    rc, out, err = run(envelope([ev(0, "edge", "alice", "external", bytes(b).hex())], cfg))
    if rc != 0:
        mut_bad += 1
        print("MUT BAD EXIT", rc, err[:400])
        print(bytes(b)[:200])
        break
    d = json.loads(out)
    r = d["results"][0]
    if r["decision"] == "reject":
        assert r["reason"] in ("hex","syntax","headers","length","fields","auth","identity","conflict"), r
    else:
        assert set(r.keys()) == {"index","decision","first","account","identity","from","pai","method","target","call_id","cseq","tag","privacy","body_sha256"}, r
print("mutation fuzz done, bad exits:", mut_bad)
summary()
